<div class="page-heading"><div><span class="eyebrow">Parent · Booking history</span><h1>My bookings</h1><p>Track each appointment request from admin review to hospital outcome.</p></div><a class="button" href="<?= e(url('parent.hospitals')) ?>">New booking</a></div>
<section class="booking-list"><?php foreach ($bookings as $booking): ?><article><div class="date-tile large"><strong><?= e(display_date($booking['appointment_date'], 'd')) ?></strong><span><?= e(display_date($booking['appointment_date'], 'M Y')) ?></span><small><?= e(display_date($booking['appointment_time'], 'g:i A')) ?></small></div><div class="booking-main"><div class="card-top"><span class="status status-<?= e($booking['status']) ?>"><?= e(status_label($booking['status'])) ?></span><small>Requested <?= e(display_date($booking['created_at'])) ?></small></div><h2><?= e($booking['child_name']) ?> · <?= e($booking['vaccine_name']) ?></h2><p><?= e($booking['dose_label']) ?> at <?= e($booking['hospital_name']) ?>, <?= e($booking['city']) ?></p><?php if ($booking['admin_notes']): ?><div class="note"><strong>Admin note</strong><p><?= e($booking['admin_notes']) ?></p></div><?php endif; ?><?php if ($booking['hospital_notes']): ?><div class="note"><strong>Hospital note</strong><p><?= e($booking['hospital_notes']) ?></p></div><?php endif; ?></div></article><?php endforeach; ?><?php if (!$bookings): ?><div class="empty-state compact"><span class="empty-icon">↗</span><h2>No bookings yet</h2><p>Search hospitals and request the first appointment.</p><a class="button" href="<?= e(url('parent.hospitals')) ?>">Find hospital</a></div><?php endif; ?></section>
